from collections import deque, defaultdict
from heapq import heappop, heappush
import math

def shortest_path(graph, source, target):
    # Helper function to perform BFS and return the shortest path
    def bfs(source, target):
        if source == target:
            return [source]

        visited = set()
        queue = deque([(source, [])])
        while queue:
            node, path = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor, _ in graph[node]:
                    if neighbor == target:
                        return path + [neighbor]
                    queue.append((neighbor, path + [node]))
        return None

    # Helper function to perform DFS and return the shortest path
    def dfs(source, target, path, visited):
        if source == target:
            return path + [target]
        visited.add(source)
        for neighbor, _ in graph[source]:
            if neighbor not in visited:
                path = dfs(neighbor, target, path + [source], visited)
                if path:
                    return path
        return None

    # Check if the source is the same as the target (trivial case)
    if source == target:
        return (0, [source])

    # Perform BFS if the target is not in the source's neighbors
    if target not in graph[source]:
        return (math.inf, None)

    # Perform BFS to find a path
    path1 = bfs(source, target)
    if path1:
        return (len(path1) - 1, path1)  # Distance is the length of the path minus one

    # Perform DFS to find a path
    path2 = dfs(source, target, [source], set())
    if path2:
        return (len(path2) - 1, path2)  # Distance is the length of the path minus one

    # If neither BFS nor DFS found a path, return infinity and None
    return (math.inf, None)

