def shortest_path(graph, source, target):
    # Initialize the distances to all nodes as infinity except for the source node which is 0.
    dist = {node: float("inf") for node in graph} 
    dist[source] = 0

    # Initialize the queue with all the nodes that can be reached directly from the source node.
    from collections import deque
    queue = deque([source])

    # Dictionary to keep track of the previous node for each node in the path.
    prev = {node: None for node in graph}

    while queue:
        current_node = queue.popleft()

        # If we reach the target node, reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = prev[current_node]
            return (dist[target], path[::-1])

        # Explore all neighbors of the current node
        for neighbor, weight in graph[current_node]:
            distance = dist[current_node] + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                prev[neighbor] = current_node
                queue.append(neighbor)

    # If we exit the loop, it means the target node is not reachable from the source node.
    return (float("inf"), None)
