import heapq

def shortest_path(graph, source, target):
    # Priority queue to process nodes, (distance, node)
    queue = [(0, source)]
    # Dictionary to store the shortest distance from source to each node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Dictionary to store the shortest path from source to each node
    previous_nodes = {node: None for node in graph}
    # Dictionary to store the actual path
    path = {node: [] for node in graph}

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_node == target:
            # Reconstruct the shortest path from source to target
            path[target] = [target]
            node = target
            while node != source:
                path[target].insert(0, previous_nodes[node])
                node = previous_nodes[node]
            return (current_distance, path[target])

        if current_distance < distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))
                # Update the path for the new distance
                path[neighbor] = path[current_node] + [neighbor]

    # If we reach here, it means the target was unreachable
    return (float('inf'), None)

