def get_path(node, graph, distances):
    path = []
    while node:
        path.append(node)
        if distances[node] == float("inf"):
            break
        node = next((neighbor for neighbor in graph if neighbor[0] == node and distances[neighbor[0]] == distances[node] - neighbor[1]), None)
    return path[::-1]

