from collections import deque

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    def bfs_shortest_path(graph, source, target):
        distances = {node: float("inf") for node in graph}
        distances[source] = 0
        queue = deque([source])

        while queue:
            current = queue.popleft()
            for neighbor, weight in graph[current]:
                if distances[current] + weight < distances[neighbor]:
                    distances[neighbor] = distances[current] + weight
                    queue.append(neighbor)

        return distances[target] if distances[target] != float("inf") else float("inf"), None

    def dfs_shortest_path(graph, source, target, path=None):
        if path is None:
            path = [source]
        if source == target:
            return path

        for neighbor, weight in graph[source]:
            if neighbor not in path:
                path_copy = path.copy()
                path_copy.append(neighbor)
                result = dfs_shortest_path(graph, neighbor, target, path_copy)
                if result:
                    return result
        return None

    # Here we try BFS first, because for non-negative weights, it always finds the shortest path.
    bfs_result, _ = bfs_shortest_path(graph, source, target)
    if bfs_result != float("inf"):
        return bfs_result, path

    # If BFS doesn't find a path, we try DFS
    dfs_result = dfs_shortest_path(graph, source, target)
    return dfs_result, None

