from collections import defaultdict, deque
import math

def shortest_path(graph, source, target):
    def bfs(graph, source, target):
        if target not in graph:
            return float("inf"), None
        visited = set()
        queue = deque([(source, [source])])

        while queue:
            current, path = queue.popleft()
            if current == target:
                return len(path), path
            visited.add(current)
            for neighbor, weight in graph[current]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
        return float("inf"), None

    def dfs(graph, source, target, visited=None):
        if visited is None:
            visited = set()
        visited.add(source)
        if source == target:
            return 0, [source]
        min_distance = math.inf
        for neighbor, weight in graph[source]:
            if neighbor not in visited:
                distance, path = dfs(graph, neighbor, target, visited)
                if distance != math.inf:
                    total_distance = distance + weight
                    if total_distance < min_distance:
                        min_distance = total_distance
                        path = [source] + path
        return min_distance, path

    # Try BFS first as it's more efficient for finding shortest path
    distance, path = bfs(graph, source, target)
    if distance != math.inf:
        return distance, path

    # If BFS didn't find the path, try DFS
    distance, path = dfs(graph, source, target)
    return distance, path

